"""Frozen, deterministic single-instrument analysis of local summary tables."""
import argparse
import csv
import hashlib
import json
import math
import sys
from collections import Counter, defaultdict
from fractions import Fraction
from pathlib import Path


LETTERS = tuple("ABCDFGH")
COLS = ("variant", "chromosome", "position", "effect_allele", "other_allele",
        "beta", "standard_error", "eaf")
MISSING = ("", "NA", None)


class AnalysisError(ValueError):
    pass


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write_json(name, value):
    destination = Path("outputs") / name
    destination.write_text(json.dumps(value, indent=2, allow_nan=False) + "\n")


def number(value):
    try:
        x = float(value)
        return x if math.isfinite(x) else None
    except (ValueError, TypeError):
        return None


def positive_se(row):
    x = number(row["standard_error"])
    if x is None or x <= 0:
        raise AnalysisError("Missing, nonfinite or nonpositive selected standard_error")
    return x


def coefficient(row):
    x = number(row["beta"])
    if x is None:
        raise AnalysisError("Missing or nonfinite selected beta")
    return x


def alignment(exposure, outcome):
    ep = (exposure["effect_allele"], exposure["other_allele"])
    op = (outcome["effect_allele"], outcome["other_allele"])
    if any(x in MISSING for x in ep + op) or ep[0] == ep[1] or op[0] == op[1]:
        return 1, "orientation_unresolved"
    if ep == op:
        return 1, "matched"
    if ep == op[::-1]:
        return -1, "reversed"
    return 1, "orientation_unresolved"


def classify(L, s):
    if L - 1.96 * s > 0:
        return "harmful"
    if L + 1.96 * s < 0:
        return "protective"
    return "inconclusive"


def effect(letter, exposure, outcome):
    be, se = coefficient(exposure), positive_se(exposure)
    if be == 0:
        raise AnalysisError("Selected exposure beta is zero")
    bo, so = coefficient(outcome), positive_se(outcome)
    sign, orientation = alignment(exposure, outcome)
    aligned = sign * bo
    L, s = -aligned / be, so / abs(be)
    lo, hi = L - 1.96 * s, L + 1.96 * s
    result = {"dataset": letter, "or": math.exp(L), "ci_low": math.exp(lo),
              "ci_high": math.exp(hi), "classification": classify(L, s)}
    detail = {"dataset": letter, "b_e": be, "s_e": se, "b_o_reported": bo,
              "b_o_aligned": aligned, "s_o": so, "sign": sign,
              "alignment": orientation, "exposure_alleles": [exposure[k] for k in COLS[3:5]],
              "outcome_alleles": [outcome[k] for k in COLS[3:5]],
              "L": L, "s": s, "log_odds_ci": [lo, hi],
              "p": math.erfc(abs(L / s) / math.sqrt(2)),
              "classification": result["classification"]}
    return result, detail


def magnitude_gap(details):
    selected = [d for d in details if d["classification"] != "inconclusive"]
    audit = {"S": sorted(d["dataset"] for d in selected),
             "independence": "Assumed as requested; participant overlap not observable"}
    if len(selected) < 2:
        audit["status"] = "not_evaluable: fewer than two classified effects"
        return {"estimate": 0, "ci_low": 0, "ci_high": 0}, "inconclusive", audit
    h = min(selected, key=lambda d: (-abs(d["L"]), d["dataset"]))
    m = min(selected, key=lambda d: (abs(d["L"]), d["dataset"]))
    R = abs(h["L"]) / abs(m["L"])
    w = math.hypot(h["s_o"] / h["b_o_aligned"], m["s_o"] / m["b_o_aligned"])
    log_r = math.log(R)
    low, high = R * math.exp(-1.96 * w), R * math.exp(1.96 * w)
    ratio = {"estimate": R, "ci_low": low, "ci_high": high}
    conclusion = "gap" if R >= 2 and low > 1 else "no-gap"
    audit.update({"h": h["dataset"], "m": m["dataset"], "R": R, "w": w,
                  "log_R": log_r, "log_R_ci": [log_r - 1.96 * w, log_r + 1.96 * w],
                  "directional_p": 0.5 * math.erfc(log_r / w / math.sqrt(2)),
                  "h_beta": h["b_o_aligned"], "m_beta": m["b_o_aligned"],
                  "h_se": h["s_o"], "m_se": m["s_o"],
                  "status": "exploratory; selected extrema; no selection correction"})
    return ratio, conclusion, audit


def read_table(path, required, files):
    files[str(path)] = digest(path)
    with Path(path).open(newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        if reader.fieldnames is None or not set(required) <= set(reader.fieldnames):
            raise AnalysisError("Missing required columns: " + str(path))
        rows = list(reader)
    if any(None in row for row in rows):
        raise AnalysisError("Malformed extra fields: " + str(path))
    return rows


def audit_table(letter, rows, duplicates, problems):
    groups = defaultdict(list)
    exact_seen = set()
    exact_duplicates = 0
    flags = Counter()
    coordinate_groups = defaultdict(set)
    for row in rows:
        key = tuple(row.get(c) for c in COLS)
        if key in exact_seen:
            exact_duplicates += 1
            continue
        exact_seen.add(key)
        if row["variant"] in MISSING:
            flags["missing variant code"] += 1
            continue
        groups[row["variant"]].append(row)
        if any(row[c] in MISSING for c in COLS):
            flags["rows with missing required fields"] += 1
        if row["effect_allele"] == row["other_allele"]:
            flags["identical effect_allele and other_allele"] += 1
        for col in ("beta", "standard_error", "eaf"):
            x = number(row[col])
            if x is None:
                flags["missing/nonfinite/unparseable " + col] += 1
            elif col == "standard_error" and x <= 0:
                flags["nonpositive standard_error"] += 1
            elif col == "eaf" and not 0 <= x <= 1:
                flags["eaf outside [0,1]"] += 1
        try:
            int(row["position"])
        except (ValueError, TypeError):
            flags["noninteger position"] += 1
        pair = tuple(sorted(str(row[c]) for c in COLS[3:5]))
        coordinate_groups[(row["chromosome"], row["position"], pair)].add(row["variant"])
    conflicts = sorted(k for k, values in groups.items() if len(values) > 1)
    coordinate_duplicates = sum(len(v) > 1 for v in coordinate_groups.values())
    if exact_duplicates:
        duplicates.append(f"{letter}: {exact_duplicates} identical duplicate rows collapsed")
    if conflicts:
        duplicates.append(f"{letter}: {len(conflicts)} variant codes with conflicting rows")
    if coordinate_duplicates:
        duplicates.append(f"{letter}: {coordinate_duplicates} coordinate/allele units have multiple variant codes")
    for name, count in sorted(flags.items()):
        problems.append(f"{letter}: {count} {name}")
    audit = {"rows": len(rows), "distinct_variants": len(groups),
             "identical_duplicate_rows": exact_duplicates, "conflicting_variants": conflicts,
             "duplicate_coordinate_allele_units": coordinate_duplicates, "flags": dict(flags)}
    return groups, audit


def audit_registry(rows, all_variants, duplicates, problems):
    decoded = []
    literal_cells = 0
    bad_cells = 0
    for row in rows:
        if row["namespace"] != "snp":
            continue
        item = dict(row)
        for column in ("original", "canonical", "target"):
            raw = row[column]
            try:
                value = json.loads(raw)
            except (json.JSONDecodeError, TypeError):
                # Some served development registries contain literal tokens.
                # Preserve their exact spelling, flag the encoding problem,
                # and never use the registry to merge association variants.
                value = raw
                literal_cells += 1
            if not isinstance(value, str) or value in MISSING:
                bad_cells += 1
            item[column] = value
        decoded.append(item)
    known = {r[c] for r in decoded for c in ("original", "canonical", "target")
             if isinstance(r[c], str)}
    absent = sorted(all_variants - known)
    mappings = defaultdict(set)
    for row in decoded:
        if isinstance(row["original"], str) and isinstance(row["target"], str):
            mappings[row["original"]].add(row["target"])
    ambiguous = sum(len(v) > 1 for v in mappings.values())
    repeated = len(decoded) - len({json.dumps(r, sort_keys=True) for r in decoded})
    if repeated:
        duplicates.append(f"Registry: {repeated} repeated alias records")
    if literal_cells:
        problems.append(f"Registry: {literal_cells} cells were literal tokens rather than JSON-encoded identifiers; preserved verbatim for namespace audit only")
    if bad_cells:
        problems.append(f"Registry: {bad_cells} missing/nonstring identifier cells")
    if ambiguous:
        problems.append(f"Registry: {ambiguous} original identifiers have multiple targets")
    if absent:
        problems.append(f"Registry: {len(absent)} association variant codes absent from decoded identifiers")
    return {"rows": len(rows), "snp_rows": len(decoded), "literal_cells": literal_cells,
            "invalid_cells": bad_cells, "ambiguous_mappings": ambiguous,
            "absent_variants": absent, "duplicate_rows": repeated}


def one(groups, variant, label):
    records = groups[variant]
    if len(records) != 1:
        raise AnalysisError(f"{label}/{variant}: conflicting duplicate estimates")
    return records[0]


def ordered_instruments(shared, exposure):
    scores = {}
    for variant in shared:
        row = one(exposure, variant, "E")
        coefficient(row)
        positive_se(row)
        scores[variant] = abs(Fraction(row["beta"])) / Fraction(row["standard_error"])
    return sorted(shared, key=lambda v: (-scores[v], v)), scores


def validate_report(report):
    assert set(report) == {"instrument", "ranked", "ratio", "conclusion", "data_integrity"}
    assert isinstance(report["instrument"]["n_shared"], int)
    assert len(set(report["instrument"]["top_variants"])) == 5
    assert len(report["ranked"]) == 7
    assert {r["dataset"] for r in report["ranked"]} == set(LETTERS)
    for row in report["ranked"]:
        assert set(row) == {"dataset", "or", "ci_low", "ci_high", "classification"}
        assert row["classification"] in {"harmful", "protective", "inconclusive"}
        assert 0 < row["ci_low"] <= row["or"] <= row["ci_high"]
        assert all(math.isfinite(row[k]) for k in ("or", "ci_low", "ci_high"))
    assert set(report["ratio"]) == {"estimate", "ci_low", "ci_high"}
    assert all(math.isfinite(v) for v in report["ratio"].values())
    assert report["conclusion"] in {"gap", "inconclusive", "no-gap"}
    json.dumps(report, allow_nan=False)


def run(launcher):
    Path("outputs").mkdir(exist_ok=True)
    files = {}
    state = {"files_read": files, "tables": {}, "selected": {}}
    duplicates, problems = [], []
    try:
        files["plan.json"] = digest("plan.json")
        plan = json.loads(Path("plan.json").read_text())
        files["code/public-metadata.json"] = digest("code/public-metadata.json")
        json.loads(Path("code/public-metadata.json").read_text())
        groups = {}
        for letter in "ABCDEFGH":
            role = "exposure" if letter == "E" else "outcome"
            path = f"data/{letter}-{role}.tsv"
            rows = read_table(path, COLS, files)
            groups[letter], state["tables"][letter] = audit_table(letter, rows, duplicates, problems)
        registry = read_table("data/snp-aliases.tsv", ("namespace", "encoding", "original", "canonical", "target"), files)
        all_variants = set.union(*(set(g) for g in groups.values()))
        state["registry"] = audit_registry(registry, all_variants, duplicates, problems)
        shared = set.intersection(*(set(g) for g in groups.values()))
        state["n_shared"] = len(shared)
        if len(shared) < 5:
            raise AnalysisError("Fewer than five shared variants")
        ordered, scores = ordered_instruments(shared, groups["E"])
        top = ordered[:5]
        variant = top[0]
        exposure = one(groups["E"], variant, "E")
        state["instrument"] = {"variant": variant, "top_variants": top,
                               "top_scores": {v: float(scores[v]) for v in top}}
        # Audit cross-table pairs on shared variants; flags do not change intersection.
        for letter in LETTERS:
            flags = Counter()
            for v in sorted(shared):
                if len(groups["E"][v]) != 1 or len(groups[letter][v]) != 1:
                    continue
                er, rr = groups["E"][v][0], groups[letter][v][0]
                for column in ("chromosome", "position"):
                    if er[column] != rr[column]:
                        flags[column + " differs from E"] += 1
                if alignment(er, rr)[1] == "orientation_unresolved":
                    flags["allele orientation unresolved against E"] += 1
            state["tables"][letter]["cross_table_flags"] = dict(flags)
            problems.extend(f"{letter}: {n} shared variants with {name}" for name, n in sorted(flags.items()))
        results, details = [], []
        for letter in LETTERS:
            outcome = one(groups[letter], variant, letter)
            result, detail = effect(letter, exposure, outcome)
            results.append(result)
            details.append(detail)
            state["selected"][letter] = detail
            if detail["alignment"] == "orientation_unresolved":
                problems.append(f"{letter}/{variant}: orientation_unresolved; E alleles {detail['exposure_alleles']}, outcome alleles {detail['outcome_alleles']}. Numeric odds ratio, interval and classification assume the reported effect orientation agrees with E; directional inference is not verified.")
        detail_map = {d["dataset"]: d for d in details}
        results.sort(key=lambda r: (-abs(detail_map[r["dataset"]]["L"]), r["dataset"]))
        ratio, conclusion, gap = magnitude_gap(details)
        state["gap"] = gap
        state["limitations"] = [
            "No participant identifiers: sample overlap is not observable.",
            "Independent outcomes assumed for the gap interval.",
            "One common exposure-selected variant; no LD-based independent variant count.",
            "Pointwise normal intervals; exposure uncertainty omitted as requested.",
            "Exploratory cross-table estimators; no registered kernel decision interval.",
            "S and magnitude extrema selected from the same estimates; no selection correction.",
            "Unresolved orientation yields conditional signed estimates only; sign reversal leaves abs(L), S membership and gap invariant."
        ]
        report = {"instrument": {"n_shared": len(shared), "top_variants": top},
                  "ranked": results, "ratio": ratio, "conclusion": conclusion,
                  "data_integrity": {"duplicate_units": duplicates, "other_problems": problems,
                    "units_of_analysis": plan["sharedKnobs"]["data_integrity"]["units_of_analysis"]}}
        validate_report(report)
        primary, diagnostics = {}, {}
        for claim in plan["claims"]:
            cid = claim["id"]
            if cid == "effect_magnitude_gap":
                if "log_R" not in gap:
                    primary[cid] = {"status": "not_evaluable", "n_units": len(gap["S"]),
                                    "reason": "Fewer than two classified effects; log gap ratio has no estimate. Task ratio zeros are sentinels, not primary estimates."}
                else:
                    primary[cid] = {"estimate": gap["log_R"], "se": gap["w"],
                                    "p": gap["directional_p"], "n_units": 2,
                                    "status": "Tentative", "method": "independent-summary delta method; selected extrema"}
                    diagnostics[cid] = {"method": "Task-prescribed normal delta interval on log R; not a registered decision interval",
                                        "log_R_ci": gap["log_R_ci"], "ratio": ratio}
            else:
                letter = Path(claim["table"]).name.split("-", 1)[0]
                d = detail_map[letter]
                primary[cid] = {"estimate": d["L"], "se": d["s"], "p": d["p"],
                                "n_units": 1, "status": "Tentative", "alignment": d["alignment"],
                                "directional_inference_verified": d["alignment"] != "orientation_unresolved",
                                "method": "summary-statistic normal Wald ratio; exposure uncertainty omitted"}
                if d["alignment"] == "orientation_unresolved":
                    primary[cid]["assumption"] = "Reported outcome effect orientation agrees with E; not verified"
                    primary[cid]["exposure_alleles"] = d["exposure_alleles"]
                    primary[cid]["outcome_alleles"] = d["outcome_alleles"]
                diagnostics[cid] = {"method": "Task-prescribed normal Wald interval; not a registered decision interval",
                                    "log_odds_ci": d["log_odds_ci"]}
        assert set(primary) == {c["id"] for c in plan["claims"]}
        write_json("task-results.json", report)
        write_json("report.json", report)
        write_json("primary.json", {"claims": primary})
        write_json("diagnostics.json", {"claims": diagnostics})
        write_json("audit.json", state)
        sources = ["code/analyze.py", "code/public-metadata.json", "run_all.sh", "run_primary.sh"]
        write_json("provenance.json", {"files_read": files, "sources": {p: digest(p) for p in sources},
                     "plan_sha256": files["plan.json"], "python": sys.version,
                     "libraries": "Python standard library only", "launcher": launcher,
                     "code_command": ["python", "-B", "code/analyze.py", "--launcher", launcher],
                     "claim_ids": [c["id"] for c in plan["claims"]],
                     "paper_set_as_locked": plan["paper_set"],
                     "note": "Primary keys preserve claims[].id exactly; intervals are diagnostics, not registered kernel intervals."})
        print("Wrote outputs/task-results.json, report.json, primary.json, diagnostics.json, audit.json and provenance.json")
        print(f"Computed seven outcome estimates with one instrument; {len(primary)} scientific claim blocks.")
    except (AnalysisError, ValueError, OverflowError, AssertionError) as exc:
        state["failure"] = str(exc)
        state["duplicate_units"] = duplicates
        state["other_problems"] = problems
        write_json("audit.json", state)
        write_json("failure.json", {"status": "not_evaluable", "reason": str(exc),
                                   "no_substitution": "No alternative instrument, estimator, or invented estimate was used"})
        raise


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--launcher", default="direct")
    args = parser.parse_args()
    run(args.launcher)
